            raise ValueError("Leave request must be made at least 3 days in advance.")

        # Calculate needed days per year
        days_by_year: dict[int, int] = defaultdict(int)
        curr = start
        one_day = timedelta(days=1)
        total_days = 0

        while curr <= end:
            # Check if it's a weekday (0=Monday, ..., 4=Friday, 5=Saturday, 6=Sunday)
            if curr.weekday() < 5 and curr not in self.holidays:
                days_by_year[curr.year] += 1
                total_days += 1
            curr += one_day

        # Check if the employee has enough remaining days for each year spanned
        for year, needed in days_by_year.items():
            if self.remaining(employee, year) < needed:
                raise ValueError(
                    f"Not enough leave days remaining in {year} (needed {needed}, remaining {self.remaining(employee, year)})."
                )

        # Deduct days
        for year, needed in days_by_year.items():
            self._used[employee][year] += needed

        self._requested_employees.add(employee)
        self._requests[employee].append((start, end))

        return total_days

    def remaining(self, employee: str, year: int) -> int:
        # Avoid creating entries in defaultdict when checking remaining days
        if employee in self._used and year in self._used[employee]:
            used = self._used[employee][year]
        else:
            used = 0
        return self.days_per_year - used

    def employees(self) -> list[str]:
        """Return all employees with at least one request, sorted."""
        return sorted(self._requested_employees)

    def requests_of(self, employee: str) -> list[tuple[date, date]]:
        """Return the employee's requests."""
        return list(self._requests.get(employee, []))
